<template><div class="page"><SiteNav active="projects"/><main><section class="projects-hero"><div class="shell"><p class="eyebrow">Proof of work / deployed systems</p><h1 class="page-title">Projects with a <em>working destination.</em></h1><p class="intro">This is not a gallery of mockups. Each project links to a live system and its source history so you can see the actual product context.</p></div></section><section class="project-field"><div class="shell"><article v-for="(project,index) in projects" :key="project.title" class="case"><div class="case-label"><span>CASE / 0{{index+1}}</span><i>{{project.category}}</i></div><a :href="project.live" target="_blank" rel="noopener" class="case-image"><img :src="project.image" :alt="project.title"/><span>Live product ↗</span></a><div class="case-info"><div><h2>{{project.title}}</h2><p>{{project.description}}</p></div><div class="case-actions"><div class="tags"><span v-for="tech in project.stack" :key="tech" class="tag">{{tech}}</span></div><div><a class="button primary" :href="project.live" target="_blank" rel="noopener">Open live system ↗</a><a class="source" :href="project.source" target="_blank" rel="noopener">View source <b>↗</b></a></div></div></div></article></div></section><section class="closing"><div class="shell"><p class="eyebrow">More work available on request</p><h2>Need a build, a careful test pass, or a documented handover?</h2><a :href="base+'contact/'" class="button ghost">Start a conversation ↗</a></div></section></main><SiteFooter/></div></template>
